// Dogfight — pixel-art fighter jets fighting each other over the desktop.
// Sprites are generated by tools/gen_jets.py (top-down, nose to the right;
// jets are rotated with Clutter so any heading is smooth).
// Same skeleton as fox-pet@local: tick loop, layer placement, panel menu.

import GLib from 'gi://GLib';
import Gio from 'gi://Gio';
import St from 'gi://St';

import * as Main from 'resource:///org/gnome/shell/ui/main.js';
import * as PanelMenu from 'resource:///org/gnome/shell/ui/panelMenu.js';
import * as PopupMenu from 'resource:///org/gnome/shell/ui/popupMenu.js';
import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';

const TICK_MS = 33;

// sprite sizes in logical px (see gen_jets.py, scale x3)
const JET_W = 78, JET_H = 57;
const EXPL = 72;
const PUFF = 30;
const SPARK = 21;

const TEAMS = ['red', 'blue'];
const TEAM_NAMES = {red: 'красные', blue: 'синие'};
const TRACER = {red: '#ffcf6a', blue: '#9fe6ff'};

const MAX_HP = 10;
const SPEED = 7;            // px/tick (x scale factor)
const TURN = 0.075;         // rad/tick
const BULLET_SPEED = 21;
const BULLET_LIFE = 24;
const HIT_R = 12;
const EXPL_TICKS = 24;      // 6 frames x 4 ticks

const DEFAULTS = {visible: true, aboveWindows: true, perTeam: 2};

const rand = (a, b) => a + Math.random() * (b - a);
const randi = (a, b) => Math.floor(rand(a, b + 1));
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const angDiff = (a, b) => Math.atan2(Math.sin(a - b), Math.cos(a - b));

function sprite(dir, name, w, h) {
    const path = GLib.build_filenamev([dir, 'sprites', `${name}.png`]);
    return new St.Widget({
        reactive: false,
        style: `background-image: url("${path}"); width: ${w}px; height: ${h}px;`,
    });
}

// ------------------------------------------------------------------ jets

class Jet {
    constructor(world, team) {
        this.world = world;
        this.team = team;
        const sf = world.sf;
        this.w = JET_W * sf;
        this.h = JET_H * sf;
        this.actor = new St.Widget({reactive: false, width: this.w, height: this.h, visible: false});
        this.actor.set_pivot_point(0.5, 0.5);
        this._frames = [0, 1].map(i => {
            const f = sprite(world.dir, `jet_${team}_${i}`, JET_W, JET_H);
            f.visible = i === 0;
            this.actor.add_child(f);
            return f;
        });
        world.layer.add_child(this.actor);
        this.skill = rand(0.85, 1.15);
        this.dead = true;
        this.respawnT = 0;
        this.age = 0;
    }

    spawn(side = null) {
        const [x0, y0, x1, y1] = this.world.bounds;
        const m = 40 * this.world.sf;
        side ??= randi(0, 3);
        switch (side) {
        case 0: this.x = x0 - m; this.y = rand(y0, y1); break;      // left
        case 1: this.x = x1 + m; this.y = rand(y0, y1); break;      // right
        case 2: this.x = rand(x0, x1); this.y = y0 - m; break;      // top
        default: this.x = rand(x0, x1); this.y = y1 + m;            // bottom
        }
        const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
        this.a = Math.atan2(cy - this.y, cx - this.x) + rand(-0.4, 0.4);
        this.v = SPEED * this.world.sf;
        this.hp = MAX_HP;
        this.state = 'attack';
        this.stateT = 0;
        this.target = null;
        this.cool = randi(10, 30);
        this.burst = randi(4, 8);
        this.dead = false;
        this.actor.show();
    }

    get vx() {
        return Math.cos(this.a) * this.v;
    }

    get vy() {
        return Math.sin(this.a) * this.v;
    }

    _pickTarget(enemies) {
        let best = null, bd = Infinity;
        for (const e of enemies) {
            const d = Math.hypot(e.x - this.x, e.y - this.y);
            if (d < bd) {
                bd = d;
                best = e;
            }
        }
        // stick to the current target unless another one is much closer
        if (this.target && !this.target.dead) {
            const cd = Math.hypot(this.target.x - this.x, this.target.y - this.y);
            if (cd < bd * 1.5)
                return this.target;
        }
        return best;
    }

    _threatened(enemies) {
        const sf = this.world.sf;
        for (const e of enemies) {
            const d = Math.hypot(e.x - this.x, e.y - this.y);
            if (d > 380 * sf)
                continue;
            const aim = Math.abs(angDiff(e.a, Math.atan2(this.y - e.y, this.x - e.x)));
            const behind = Math.abs(angDiff(this.a, Math.atan2(e.y - this.y, e.x - this.x))) > 2.0;
            if (aim < 0.35 && behind)
                return true;
        }
        return false;
    }

    think() {
        const w = this.world;
        const sf = w.sf;
        const enemies = w.jets.filter(j => !j.dead && j.team !== this.team);
        this.target = enemies.length ? this._pickTarget(enemies) : null;

        let desired = this.a;
        let leadErr = Infinity;
        let dist = Infinity;
        const t = this.target;

        if (this.state === 'evade' || this.state === 'extend') {
            if (--this.stateT <= 0)
                this.state = 'attack';
        }

        if (this.state === 'evade') {
            desired = this.a + this.turnDir * 1.6;
        } else if (this.state === 'extend') {
            desired = this.a;
        } else if (t) {
            dist = Math.hypot(t.x - this.x, t.y - this.y);
            const lt = dist / (BULLET_SPEED * sf);
            const px = t.x + t.vx * lt, py = t.y + t.vy * lt;
            desired = Math.atan2(py - this.y, px - this.x);
            leadErr = Math.abs(angDiff(desired, this.a));
            if (this._threatened(enemies) && Math.random() < 0.05) {
                this.state = 'evade';
                this.stateT = randi(25, 50);
                this.turnDir = Math.random() < 0.5 ? -1 : 1;
            } else if (dist < 110 * sf && leadErr < 1.2) {
                // about to overshoot: fly through and come around again
                this.state = 'extend';
                this.stateT = randi(20, 35);
            }
        } else {
            // nobody to fight: lazy circles around the centre
            const [x0, y0, x1, y1] = w.bounds;
            desired = Math.atan2((y0 + y1) / 2 - this.y, (x0 + x1) / 2 - this.x) + 1.2;
        }

        // don't ram anybody
        for (const o of w.jets) {
            if (o === this || o.dead)
                continue;
            const d = Math.hypot(o.x - this.x, o.y - this.y);
            if (d < 60 * sf) {
                const away = Math.atan2(this.y - o.y, this.x - o.x);
                desired += angDiff(away, desired) * 0.6;
            }
        }

        // stay over the screen: steer back towards the centre near the edges
        const [x0, y0, x1, y1] = w.bounds;
        const m = 140 * sf;
        const out = Math.max(x0 + m - this.x, this.x - (x1 - m), y0 + m - this.y, this.y - (y1 - m), 0) / m;
        if (out > 0) {
            const home = Math.atan2((y0 + y1) / 2 - this.y, (x0 + x1) / 2 - this.x);
            desired += angDiff(home, desired) * Math.min(1, out);
        }

        const rate = TURN * this.skill * (this.state === 'evade' ? 1.35 : 1);
        this.a += clamp(angDiff(desired, this.a), -rate, rate);
        const vt = SPEED * sf * this.skill * (this.state === 'evade' ? 1.2 : this.state === 'extend' ? 1.15 : 1);
        this.v += (vt - this.v) * 0.05;

        // guns
        if (this.cool > 0)
            this.cool--;
        if (this.state === 'attack' && t && dist < 460 * sf && leadErr < 0.12 && this.cool === 0) {
            w.fire(this);
            this.burst--;
            if (this.burst > 0) {
                this.cool = 3;
            } else {
                this.cool = randi(18, 35);
                this.burst = randi(4, 8);
            }
        }
    }

    tick() {
        if (this.dead) {
            if (--this.respawnT <= 0)
                this.spawn();
            return;
        }
        this.age++;
        this.think();
        this.x += this.vx;
        this.y += this.vy;

        // damaged: trail of smoke from the tail
        if (this.hp <= MAX_HP / 2 && this.age % (this.hp <= 1 ? 2 : 3) === 0) {
            const tx = this.x - Math.cos(this.a) * this.w * 0.4;
            const ty = this.y - Math.sin(this.a) * this.w * 0.4;
            this.world.fx.puff(tx, ty, this.hp <= 1 ? 1.4 : 1.0, 36);
        }
    }

    hit(by) {
        this.hp--;
        if (this.hp <= 0)
            this.world.kill(this, by);
    }

    render() {
        if (this.dead)
            return;
        const f = Math.floor(this.age / 2) % 2;
        this._frames[f].show();
        this._frames[1 - f].hide();
        this.actor.set_position(Math.round(this.x - this.w / 2), Math.round(this.y - this.h / 2));
        this.actor.rotation_angle_z = this.a * 180 / Math.PI;
    }

    destroy() {
        this.actor.destroy();
    }
}

// --------------------------------------------------------------- effects

class Effects {
    constructor(world) {
        this.world = world;
        this._puffs = [];
        this._sparks = [];
        this._expls = [];
    }

    _get(pool, make, cap) {
        let it = pool.find(p => p.life <= 0);
        if (!it) {
            if (pool.length >= cap)
                return null;
            it = make();
            pool.push(it);
        }
        return it;
    }

    _simple(name, size) {
        const sf = this.world.sf;
        const actor = sprite(this.world.dir, name, size, size);
        actor.set_size(size * sf, size * sf);
        actor.set_pivot_point(0.5, 0.5);
        actor.hide();
        this.world.layer.insert_child_at_index(actor, 0); // below the jets
        return {actor, life: 0, age: 0, size: size * sf};
    }

    puff(x, y, scale, life) {
        const p = this._get(this._puffs, () => this._simple('puff', PUFF), 160);
        if (!p)
            return;
        Object.assign(p, {x: x + rand(-3, 3), y: y + rand(-3, 3), life, max: life, age: 0, s: scale});
        p.actor.show();
    }

    spark(x, y) {
        const p = this._get(this._sparks, () => this._simple('spark', SPARK), 40);
        if (!p)
            return;
        Object.assign(p, {x, y, life: 6, max: 6, age: 0, s: 1});
        p.actor.rotation_angle_z = rand(0, 90);
        p.actor.show();
    }

    explode(x, y, vx, vy) {
        const p = this._get(this._expls, () => {
            const sf = this.world.sf;
            const actor = new St.Widget({reactive: false, width: EXPL * sf, height: EXPL * sf, visible: false});
            const frames = [];
            for (let i = 0; i < 6; i++) {
                const f = sprite(this.world.dir, `expl_${i}`, EXPL, EXPL);
                f.visible = false;
                actor.add_child(f);
                frames.push(f);
            }
            this.world.layer.add_child(actor);
            return {actor, frames, life: 0, size: EXPL * sf, shown: -1};
        }, 12);
        if (!p)
            return;
        Object.assign(p, {x, y, vx: vx * 0.3, vy: vy * 0.3, life: EXPL_TICKS, age: 0});
        p.actor.show();
        for (let k = 0; k < 6; k++)
            this.puff(x + rand(-20, 20), y + rand(-20, 20), 1.6, randi(40, 70));
    }

    tick() {
        for (const p of this._puffs) {
            if (p.life <= 0)
                continue;
            p.age++;
            if (--p.life <= 0) {
                p.actor.hide();
                continue;
            }
            const k = p.age / p.max;
            p.y -= 0.2;
            p.actor.set_position(Math.round(p.x - p.size / 2), Math.round(p.y - p.size / 2));
            p.actor.opacity = Math.round(210 * (1 - k));
            p.actor.set_scale(p.s * (0.6 + 1.2 * k), p.s * (0.6 + 1.2 * k));
        }
        for (const p of this._sparks) {
            if (p.life <= 0)
                continue;
            if (--p.life <= 0) {
                p.actor.hide();
                continue;
            }
            p.actor.set_position(Math.round(p.x - p.size / 2), Math.round(p.y - p.size / 2));
            p.actor.opacity = Math.round(255 * p.life / p.max);
        }
        for (const p of this._expls) {
            if (p.life <= 0)
                continue;
            p.age++;
            p.x += p.vx;
            p.y += p.vy;
            if (--p.life <= 0) {
                p.actor.hide();
                if (p.shown >= 0)
                    p.frames[p.shown].hide();
                p.shown = -1;
                continue;
            }
            const f = Math.min(5, Math.floor(p.age / 4));
            if (f !== p.shown) {
                if (p.shown >= 0)
                    p.frames[p.shown].hide();
                p.frames[f].show();
                p.shown = f;
            }
            p.actor.set_position(Math.round(p.x - p.size / 2), Math.round(p.y - p.size / 2));
        }
    }

    clear() {
        for (const p of [...this._puffs, ...this._sparks, ...this._expls]) {
            p.life = 0;
            p.actor.hide();
        }
    }
}

// ----------------------------------------------------------------- world

class World {
    constructor(dir, perTeam, onScore) {
        this.dir = dir;
        this.sf = St.ThemeContext.get_for_stage(global.stage).scale_factor;
        this.onScore = onScore;
        this.layer = new St.Widget({reactive: false});
        this.layer.connect('destroy', () => {
            this.dead = true;
        });
        this.dead = false;
        this.score = {red: 0, blue: 0};
        this.fx = new Effects(this);
        this.bullets = [];
        this.jets = [];
        this.updateBounds();
        this.setPerTeam(perTeam);
    }

    updateBounds() {
        const lm = Main.layoutManager;
        const was = lm.monitors.map((_m, i) => lm.getWorkAreaForMonitor(i));
        this.bounds = [
            Math.min(...was.map(r => r.x)),
            Math.min(...was.map(r => r.y)),
            Math.max(...was.map(r => r.x + r.width)),
            Math.max(...was.map(r => r.y + r.height)),
        ];
    }

    monitorIndex() {
        return Main.layoutManager.primaryIndex;
    }

    setPerTeam(n) {
        this.jets.forEach(j => j.destroy());
        this.jets = [];
        this.bullets.forEach(b => {
            b.life = 0;
            b.actor.hide();
        });
        this.fx.clear();
        for (const team of TEAMS) {
            for (let i = 0; i < n; i++) {
                const j = new Jet(this, team);
                j.spawn(team === 'red' ? 0 : 1); // teams start on opposite sides
                this.jets.push(j);
            }
        }
    }

    reset() {
        this.score = {red: 0, blue: 0};
        this.onScore?.(this.score);
        this.setPerTeam(this.jets.length / 2);
    }

    fire(j) {
        const sf = this.sf;
        let b = this.bullets.find(x => x.life <= 0);
        if (!b) {
            if (this.bullets.length >= 120)
                return;
            const actor = new St.Widget({reactive: false, visible: false});
            actor.set_size(11 * sf, 3 * sf);
            actor.set_pivot_point(0.5, 0.5);
            this.layer.add_child(actor);
            b = {actor};
            this.bullets.push(b);
        }
        const a = j.a + rand(-0.08, 0.08);
        const nose = j.w * 0.38;
        Object.assign(b, {
            x: j.x + Math.cos(j.a) * nose,
            y: j.y + Math.sin(j.a) * nose,
            vx: Math.cos(a) * BULLET_SPEED * sf + j.vx * 0.5,
            vy: Math.sin(a) * BULLET_SPEED * sf + j.vy * 0.5,
            a,
            life: BULLET_LIFE,
            owner: j,
        });
        b.actor.style = `background-color: ${TRACER[j.team]}; border-radius: 2px;`;
        b.actor.rotation_angle_z = a * 180 / Math.PI;
        b.actor.show();
    }

    kill(j, by) {
        this.fx.explode(j.x, j.y, j.vx, j.vy);
        j.dead = true;
        j.actor.hide();
        j.respawnT = randi(70, 130);
        if (by && by.team !== j.team) {
            this.score[by.team]++;
            this.onScore?.(this.score);
        }
    }

    tick() {
        for (const j of this.jets)
            j.tick();

        const sf = this.sf;
        const hr = HIT_R * sf;
        for (const b of this.bullets) {
            if (b.life <= 0)
                continue;
            b.x += b.vx;
            b.y += b.vy;
            let gone = --b.life <= 0;
            if (!gone) {
                for (const j of this.jets) {
                    if (j.dead || j.team === b.owner.team)
                        continue;
                    if (Math.hypot(j.x - b.x, j.y - b.y) < hr) {
                        this.fx.spark(b.x, b.y);
                        j.hit(b.owner);
                        gone = true;
                        break;
                    }
                }
            }
            if (gone) {
                b.life = 0;
                b.actor.hide();
                continue;
            }
            b.actor.set_position(Math.round(b.x - 5.5 * sf), Math.round(b.y - 1.5 * sf));
        }

        this.fx.tick();
        for (const j of this.jets)
            j.render();
    }

    destroy() {
        if (!this.dead)
            this.layer.destroy();
    }
}

// ------------------------------------------------------------- extension

export default class DogfightExtension extends Extension {
    enable() {
        this._settingsPath = GLib.build_filenamev([GLib.get_user_config_dir(), 'dogfight.json']);
        this._settings = {...DEFAULTS, ...this._loadSettings()};
        this._settings.perTeam = clamp(Math.round(this._settings.perTeam) || 2, 1, 4);

        this._world = new World(this.path, this._settings.perTeam, s => this._updateScore(s));
        this._placeActor();
        this._buildIndicator();

        this._overviewIds = [
            Main.overview.connect('showing', () => this._updateVisibility()),
            Main.overview.connect('hidden', () => this._updateVisibility()),
        ];
        this._fsId = global.display.connect('in-fullscreen-changed', () => this._updateVisibility());
        this._monId = Main.layoutManager.connect('monitors-changed', () => {
            this._world.updateBounds();
            this._updateVisibility();
        });
        this._waId = global.display.connect('workareas-changed', () => this._world.updateBounds());

        this._timer = GLib.timeout_add(GLib.PRIORITY_DEFAULT, TICK_MS, () => {
            if (this._world.dead)
                return GLib.SOURCE_REMOVE;
            if (this._world.layer.visible)
                this._world.tick();
            return GLib.SOURCE_CONTINUE;
        });
        this._updateVisibility();
    }

    disable() {
        if (this._timer) {
            GLib.source_remove(this._timer);
            this._timer = 0;
        }
        this._overviewIds?.forEach(id => Main.overview.disconnect(id));
        this._overviewIds = null;
        if (this._fsId)
            global.display.disconnect(this._fsId);
        if (this._waId)
            global.display.disconnect(this._waId);
        if (this._monId)
            Main.layoutManager.disconnect(this._monId);
        this._fsId = this._waId = this._monId = 0;
        this._indicator?.destroy();
        this._indicator = null;
        this._world?.destroy();
        this._world = null;
    }

    // ---------------------------------------------------------- helpers

    _loadSettings() {
        try {
            const [ok, bytes] = GLib.file_get_contents(this._settingsPath);
            if (ok)
                return JSON.parse(new TextDecoder().decode(bytes));
        } catch (e) {}
        return {};
    }

    _saveSettings() {
        try {
            GLib.file_set_contents(this._settingsPath, JSON.stringify(this._settings, null, 2));
        } catch (e) {
            console.warn(`dogfight: cannot save settings: ${e.message}`);
        }
    }

    _placeActor() {
        const actor = this._world.layer;
        actor.get_parent()?.remove_child(actor);
        if (this._settings.aboveWindows) {
            // Above windows, below the top panel / popups.
            Main.layoutManager.uiGroup.insert_child_below(actor, Main.layoutManager.panelBox);
        } else {
            // On the desktop: right above the wallpaper, below all windows.
            global.window_group.insert_child_above(actor, Main.layoutManager._backgroundGroup);
        }
    }

    _updateVisibility() {
        if (!this._world)
            return;
        const fullscreen = this._settings.aboveWindows &&
            Main.layoutManager.monitors.some(m => m.inFullscreen);
        this._world.layer.visible = this._settings.visible && !Main.overview.visible && !fullscreen;
    }

    _updateScore(s) {
        if (this._scoreItem)
            this._scoreItem.label.text = `Счёт: ${TEAM_NAMES.red} ${s.red} : ${s.blue} ${TEAM_NAMES.blue}`;
    }

    _buildIndicator() {
        this._indicator = new PanelMenu.Button(0.0, 'Dogfight', false);
        this._indicator.add_child(new St.Icon({
            gicon: Gio.FileIcon.new(Gio.File.new_for_path(GLib.build_filenamev([this.path, 'icon.png']))),
            style_class: 'system-status-icon',
        }));
        const menu = this._indicator.menu;

        this._scoreItem = new PopupMenu.PopupMenuItem('', {reactive: false});
        menu.addMenuItem(this._scoreItem);
        this._updateScore(this._world.score);
        menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());

        const show = new PopupMenu.PopupSwitchMenuItem('Показывать бой', this._settings.visible);
        show.connect('toggled', (_i, v) => {
            this._settings.visible = v;
            this._saveSettings();
            this._updateVisibility();
        });
        menu.addMenuItem(show);

        const above = new PopupMenu.PopupSwitchMenuItem('Поверх окон', this._settings.aboveWindows);
        above.connect('toggled', (_i, v) => {
            this._settings.aboveWindows = v;
            this._saveSettings();
            this._placeActor();
            this._updateVisibility();
        });
        menu.addMenuItem(above);

        const sub = new PopupMenu.PopupSubMenuMenuItem('Самолётов в команде');
        const items = [];
        for (let n = 1; n <= 4; n++) {
            const it = sub.menu.addAction(`${n} × ${n}`, () => {
                this._settings.perTeam = n;
                this._saveSettings();
                this._world.setPerTeam(n);
                items.forEach((x, k) => x.setOrnament(k + 1 === n ? PopupMenu.Ornament.DOT : PopupMenu.Ornament.NONE));
            });
            it.setOrnament(n === this._settings.perTeam ? PopupMenu.Ornament.DOT : PopupMenu.Ornament.NONE);
            items.push(it);
        }
        menu.addMenuItem(sub);

        menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());
        menu.addAction('Новый бой', () => this._world.reset());

        Main.panel.addToStatusArea(this.uuid, this._indicator);
    }
}
